{
  "name": "mutamayiz-homework",
  "version": "1.0.0",
  "description": "منصة رفع واجبات الطلاب — المتميز في الفلسفة وعلم النفس",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "node --watch server.js"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "dotenv": "^16.4.7",
    "express": "^4.21.2",
    "multer": "^1.4.5-lts.1",
    "nodemailer": "^6.9.16"
  }
}

require("dotenv").config();

const express = require("express");
const multer = require("multer");
const nodemailer = require("nodemailer");
const path = require("path");
const fs = require("fs");

const app = express();
const PORT = process.env.PORT || 3000;
const TEACHER_EMAIL = process.env.TEACHER_EMAIL || "ahmednagy4990@gmail.com";
const MAX_FILE_MB = 10;

const uploadDir = path.join(__dirname, "uploads");
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (_req, _file, cb) => cb(null, uploadDir),
  filename: (_req, file, cb) => {
    const safe = file.originalname.replace(/[^\w.\-()+\u0600-\u06FF\s]/g, "_");
    cb(null, `${Date.now()}-${safe}`);
  },
});

const upload = multer({
  storage,
  limits: { fileSize: MAX_FILE_MB * 1024 * 1024 },
  fileFilter: (_req, file, cb) => {
    const allowed = /^image\/(jpeg|jpg|png|webp|gif|heic|heif)$/i;
    if (allowed.test(file.mimetype)) {
      cb(null, true);
    } else {
      cb(new Error("INVALID_FILE_TYPE"));
    }
  },
});

function createTransporter() {
  const user = process.env.GMAIL_USER;
  const pass = process.env.GMAIL_APP_PASSWORD;
  if (!user || !pass) {
    return null;
  }
  return nodemailer.createTransport({
    service: "gmail",
    auth: { user, pass },
  });
}

app.use(express.static(path.join(__dirname, "public")));

app.get("/api/health", (_req, res) => {
  res.json({ ok: true, emailConfigured: Boolean(createTransporter()) });
});

app.post("/api/submit", upload.single("homework"), async (req, res) => {
  const fullName = (req.body.fullName || "").trim();
  if (!fullName || fullName.length < 3) {
    if (req.file) fs.unlinkSync(req.file.path);
    return res.status(400).json({
      error: "يرجى إدخال الاسم بالكامل (ثلاثة أحرف على الأقل).",
    });
  }

  if (!req.file) {
    return res.status(400).json({
      error: "يرجى اختيار صورة الواجب قبل الإرسال.",
    });
  }

  const transporter = createTransporter();
  if (!transporter) {
    fs.unlinkSync(req.file.path);
    return res.status(503).json({
      error:
        "خدمة البريد غير مهيأة بعد. تواصل مع الأستاذ لإكمال إعداد المنصة.",
    });
  }

  const submittedAt = new Date().toLocaleString("ar-EG", {
    timeZone: "Africa/Cairo",
    dateStyle: "full",
    timeStyle: "short",
  });

  const subject = `واجب جديد — ${fullName}`;
  const text = [
    "تم استلام واجب جديد عبر منصة المتميز في الفلسفة وعلم النفس.",
    "",
    `اسم الطالب: ${fullName}`,
    `وقت الإرسال: ${submittedAt}`,
    `اسم الملف: ${req.file.originalname}`,
  ].join("\n");

  try {
    await transporter.sendMail({
      from: `"منصة المتميز" <${process.env.GMAIL_USER}>`,
      to: TEACHER_EMAIL,
      replyTo: TEACHER_EMAIL,
      subject,
      text,
      attachments: [
        {
          filename: req.file.originalname || "homework.jpg",
          path: req.file.path,
        },
      ],
    });

    fs.unlinkSync(req.file.path);
    return res.json({
      success: true,
      message: "تم إرسال الواجب بنجاح. شكراً لك!",
    });
  } catch (err) {
    console.error("Email send failed:", err);
    if (fs.existsSync(req.file.path)) fs.unlinkSync(req.file.path);
    return res.status(500).json({
      error: "تعذر إرسال الواجب. حاول مرة أخرى أو تواصل مع الأستاذ.",
    });
  }
});

app.use((err, _req, res, next) => {
  if (err instanceof multer.MulterError) {
    if (err.code === "LIMIT_FILE_SIZE") {
      return res.status(400).json({
        error: `حجم الصورة كبير جداً. الحد الأقصى ${MAX_FILE_MB} ميجابايت.`,
      });
    }
    return res.status(400).json({ error: "خطأ في رفع الملف." });
  }
  if (err.message === "INVALID_FILE_TYPE") {
    return res.status(400).json({
      error: "نوع الملف غير مدعوم. يرجى رفع صورة (JPG, PNG, WEBP).",
    });
  }
  next(err);
});

app.listen(PORT, () => {
  console.log(`المنصة تعمل على http://localhost:${PORT}`);
});

:root {
  --bg: #f4f6f9;
  --surface: #ffffff;
  --text: #1a2332;
  --muted: #5c6778;
  --accent: #2c5282;
  --accent-dark: #1a365d;
  --success: #276749;
  --error: #c53030;
  --border: #e2e8f0;
  --shadow: 0 12px 40px rgba(26, 54, 93, 0.08);
  --radius: 16px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: "Cairo", system-ui, sans-serif;
  background: linear-gradient(160deg, #eef2f7 0%, #f8fafc 45%, #e8edf5 100%);
  color: var(--text);
  line-height: 1.6;
}

.page {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1rem 2.5rem;
}

.hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.hero-text h1 {
  margin: 0.25rem 0;
  font-size: clamp(1.35rem, 4vw, 1.75rem);
  line-height: 1.35;
  color: var(--accent-dark);
}

.eyebrow {
  margin: 0;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent);
}

.subtitle {
  margin: 0;
  font-size: 1.05rem;
  color: var(--muted);
  font-weight: 600;
}

.hero-photo img {
  width: 120px;
  height: 120px;
  object-fit: cover;
  border-radius: 50%;
  border: 4px solid var(--surface);
  box-shadow: var(--shadow);
}

.card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 1.75rem 1.5rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
}

.card h2 {
  margin: 0 0 0.5rem;
  font-size: 1.35rem;
}

.intro {
  margin: 0 0 1.5rem;
  color: var(--muted);
  font-size: 0.95rem;
}

.field {
  display: block;
  margin-bottom: 1.25rem;
}

.field > span {
  display: block;
  margin-bottom: 0.45rem;
  font-weight: 600;
  font-size: 0.95rem;
}

.field input[type="text"] {
  width: 100%;
  padding: 0.85rem 1rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  font: inherit;
  font-size: 1rem;
  background: #fafbfc;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.field input[type="text"]:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(44, 82, 130, 0.15);
}

.file-drop {
  position: relative;
  border: 2px dashed #cbd5e0;
  border-radius: 12px;
  background: #fafbfc;
  overflow: hidden;
  transition: border-color 0.15s, background 0.15s;
}

.file-drop:hover,
.file-drop:focus-within {
  border-color: var(--accent);
  background: #f7fafc;
}

.file-drop input[type="file"] {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
  width: 100%;
  height: 100%;
}

.file-drop-inner {
  padding: 1.25rem 1rem;
  text-align: center;
  min-height: 140px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.file-hint {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.file-name {
  margin: 0;
  font-weight: 600;
  font-size: 0.9rem;
  word-break: break-word;
}

#preview {
  max-width: 100%;
  max-height: 220px;
  border-radius: 8px;
  object-fit: contain;
}

button[type="submit"] {
  width: 100%;
  padding: 0.95rem 1rem;
  border: none;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
  color: #fff;
  font: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.12s, opacity 0.12s;
}

button[type="submit"]:hover:not(:disabled) {
