  margin: 1rem 0 0;
  font-weight: 600;
  font-size: 0.95rem;
}

.status.success {
  color: var(--success);
}

.status.error {
  color: var(--error);
}

.footer {
  margin-top: 1.5rem;
  text-align: center;
  color: var(--muted);
  font-size: 0.85rem;
