const form = document.getElementById("homework-form");
const fileInput = document.getElementById("homework");
const fileNameEl = document.getElementById("file-name");
const preview = document.getElementById("preview");
const fileHint = document.querySelector(".file-hint");
const statusEl = document.getElementById("status");
const submitBtn = document.getElementById("submit-btn");

function setStatus(message, type) {
  statusEl.textContent = message;
  statusEl.className = "status" + (type ? ` ${type}` : "");
}

fileInput.addEventListener("change", () => {
  const file = fileInput.files?.[0];
  if (!file) {
    fileNameEl.hidden = true;
    preview.hidden = true;
    fileHint.hidden = false;
    preview.removeAttribute("src");
    return;
  }

  fileNameEl.textContent = file.name;
  fileNameEl.hidden = false;
  fileHint.hidden = true;

  const reader = new FileReader();
  reader.onload = (e) => {
    preview.src = e.target.result;
    preview.hidden = false;
  };
  reader.readAsDataURL(file);
});

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  setStatus("");

  const fullName = document.getElementById("fullName").value.trim();
  const file = fileInput.files?.[0];

  if (fullName.length < 3) {
    setStatus("يرجى إدخال الاسم بالكامل.", "error");
    return;
  }
  if (!file) {
    setStatus("يرجى اختيار صورة الواجب.", "error");
    return;
  }

  const data = new FormData();
  data.append("fullName", fullName);
  data.append("homework", file);

  submitBtn.disabled = true;
  submitBtn.textContent = "جاري الإرسال…";
  setStatus("جاري رفع الواجب وإرساله…");

  try {
    const res = await fetch("/api/submit", {
      method: "POST",
      body: data,
    });
    const body = await res.json().catch(() => ({}));

    if (!res.ok) {
      setStatus(body.error || "حدث خطأ أثناء الإرسال.", "error");
      return;
    }

    setStatus(body.message || "تم الإرسال بنجاح.", "success");
    form.reset();
    fileNameEl.hidden = true;
    preview.hidden = true;
    fileHint.hidden = false;
    preview.removeAttribute("src");
  } catch {
    setStatus("تعذر الاتصال بالخادم. تحقق من الإنترنت وحاول مجدداً.", "error");
  } finally {
    submitBtn.disabled = false;
    submitBtn.textContent = "إرسال الواجب";
  }
});

