function isLocalRequest(req) {
  const ip = req.ip || "";
  return (
    ip === "127.0.0.1" ||
    ip === "::1" ||
    ip === "::ffff:127.0.0.1" ||
    ip.endsWith("127.0.0.1")
  );
}

function saveMailConfig(appPassword) {
  const pass = String(appPassword || "").replace(/\s/g, "");
  if (pass.length < 16) {
    return { ok: false, error: "كلمة مرور التطبيق يجب أن تكون 16 حرفاً." };
  }

  const content = [
    `GMAIL_USER=${DEFAULT_TEACHER_EMAIL}`,
    `GMAIL_APP_PASSWORD=${pass}`,
    `TEACHER_EMAIL=${DEFAULT_TEACHER_EMAIL}`,
    "PORT=3000",
    "",
  ].join("\n");

  fs.writeFileSync(ENV_PATH, content, "utf8");
  process.env.GMAIL_USER = DEFAULT_TEACHER_EMAIL;
  process.env.GMAIL_APP_PASSWORD = pass;
  process.env.TEACHER_EMAIL = DEFAULT_TEACHER_EMAIL;

  return { ok: true };
}

